def bestTower(towers, center, radius):
    best = None  # (x, y, q) of the best reachable tower so far
    for x, y, q in towers:
        # Manhattan distance to the center
        dist = abs(x - center[0]) + abs(y - center[1])
        if dist <= radius:
            if best is None:
                best = (x, y, q)
            elif q > best[2]:
                # Strictly better quality wins
                best = (x, y, q)
            elif q == best[2] and (x, y) < (best[0], best[1]):
                # Equal quality: keep the lexicographically smaller coordinate
                best = (x, y, q)
    # No reachable tower
    if best is None:
        return [-1, -1]
    return [best[0], best[1]]
